contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to withdraw for a given targetContract and asset.
    // Parameters:
    // - targetContract: the contract for which a pending flash decision might exist
    // - asset: the asset address expected in the pending decision
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read before state about the pending decision for this contract and this test contract (msg.sender for C is this test contract)
        (address before_asset, uint256 before_amount, uint256 before_unlockTime) = c.pendingFlashDecision(targetContract, address(this));
        uint256 before_c_balance = address(c).balance;

        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (address after_asset, uint256 after_amount, uint256 after_unlockTime) = c.pendingFlashDecision(targetContract, address(this));
        uint256 after_c_balance = address(c).balance;

        // General property:
        // If the call did not revert, then the pendingFlashDecision entry for (targetContract, this) must have been deleted
        // (represented by amount == 0), and the contract's balance must be less than or equal to before (asset was transferred out).
        // If the call reverted, then the pending entry must be unchanged.
        assert(
            (!reverted && after_amount == 0 && (after_c_balance <= before_c_balance))
            || (reverted && after_amount == before_amount && after_asset == before_asset && after_unlockTime == before_unlockTime)
        );
    }

    receive() external payable {}
}

