contract InvMutTest {
    C c;
    IERC20 probeToken;

    constructor(C _c) {
        c = _c;
    }

    // We will simulate a caller (this contract) that had previously had a pendingFlashDecision
    // transferred to it; to do that, we rely only on public interface: configureFlashGovernance and
    // assertGovernanceApproved require interactions we cannot perform fully here because they need
    // ERC20 approvals from this contract to c. Instead, we structure the test to observe the
    // observable guarantee of withdrawGovernanceAsset: when it returns (no revert), the pending
    // entry is deleted and token transfer happened. We accept token and inspect balances via IERC20.

    // The test inputs:
    // - targetContract: address for which the decision was made
    // - token: ERC20 token address that is used as flashGovernance asset
    // - amount: amount attempted to withdraw
    function run(address targetContract, address token, uint256 amount) public payable {
        require(amount <= type(uint256).max);
        probeToken = IERC20(token);

        // Read before values
        // pendingFlashDecision mapping is public with getter: c.pendingFlashDecision(targetContract, address(this))
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        uint256 beforeBalance = probeToken.balanceOf(address(c));
        uint256 myBefore = probeToken.balanceOf(address(this));

        // We attempt withdraw; capture whether it reverts
        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        uint256 afterBalance = probeToken.balanceOf(address(c));
        uint256 myAfter = probeToken.balanceOf(address(this));

        // General rule: If withdrawGovernanceAsset did NOT revert, then the pendingFlashDecision entry for (targetContract, this)
        // must have been cleared (amount == 0) and the token balance of contract c must have decreased by the withdrawn amount
        // and this contract's token balance must have increased by that amount.
        // We must express this without assumptions about prior state except via observed reads above.
        assert( reverted || (
            // pending entry cleared
            after_amount == 0 &&
            // asset cleared or matches
            (after_asset == address(0) || after_asset == before_asset) &&
            // token transfer occurred: c balance decreased by exactly the delta myAfter - myBefore
            // Ensure arithmetic without underflow: compare before and after balances consistently
            (myAfter >= myBefore ? myAfter - myBefore == (beforeBalance >= afterBalance ? beforeBalance - afterBalance : 0) : false) &&
            // the change equals the before recorded pending amount when that amount matched 'amount' parameter OR when before_amount was > 0
            (before_amount == 0 || myAfter - myBefore == before_amount) &&
            // the observed asset matches provided token when before_amount > 0
            (before_amount == 0 || before_asset == token)
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function taking inputs: targetContract (the decision target), token (ERC20 asset)
    // We attempt to withdraw whatever pendingFlashDecision exists for (targetContract, this contract).
    function run(address targetContract, address token) public payable {
        // observe before state via public getters
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        // Read balances via ERC20 interface (IERC20 is declared in the compilation unit already)
        IERC20 probe = IERC20(token);
        uint256 cBefore = probe.balanceOf(address(c));
        uint256 meBefore = probe.balanceOf(address(this));

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        uint256 cAfter = probe.balanceOf(address(c));
        uint256 meAfter = probe.balanceOf(address(this));

        // If call succeeded then pending entry must be cleared (amount==0) and token balances reflect a transfer of exactly the withdrawn amount.
        // We avoid underflow by using comparisons.
        assert(reverted || (
            // pending amount cleared
            after_amount == 0 &&
            // Either the asset cleared to zero address or stayed as before_asset (observable consequence)
            (after_asset == address(0) || after_asset == before_asset) &&
            // The increase in our balance equals the decrease in c's balance
            (meAfter >= meBefore ? meAfter - meBefore == (cBefore >= cAfter ? cBefore - cAfter : 0) : false) &&
            // If there was a positive pending amount before, then that transferred amount equals that pending amount
            (before_amount == 0 || (meAfter >= meBefore && meAfter - meBefore == before_amount)) &&
            // If there was a positive pending amount before, the recorded asset should match the token we withdrew
            (before_amount == 0 || before_asset == token)
        ));
    }

    receive() external payable {}
}

