contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to withdraw pending flash governance asset for (targetContract,msg.sender==this contract)
    // Inputs: target contract address, asset address (must match pending), and we observe behavior.
    function run(address targetContract, address asset) public payable {
        // No precondition on parameters.
        // Observe pending before attempting withdraw via public getter: pendingFlashDecision(targetContract, address(this))
        (uint256 before_amount, , address before_asset) = (c.pendingFlashDecision(targetContract, address(this)).amount, c.pendingFlashDecision(targetContract, address(this)).unlockTime, c.pendingFlashDecision(targetContract, address(this)).asset);
        // The above line uses the autogenerated getters; however the struct getter returns a tuple (amount, unlockTime, asset, assetBurnable) in order declared.
        // Solidity will actually return all fields; to keep it simple, re-read using full tuple:
        (uint256 p_amount, uint256 p_unlockTime, address p_asset, bool p_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // Attempt withdraw; it may revert or succeed. Must ensure contract has enough balance if transfer would send Ether? transfer is ERC20 so no Ether needed here.
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read the pending entry again
        (uint256 a_amount, uint256 a_unlockTime, address a_asset, bool a_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // General rule expressed as a single assert:
        // If the call reverted then the preconditions required by withdrawGovernanceAsset were not all met
        // (i.e. either stored asset != provided asset OR stored amount == 0 OR unlockTime >= block.timestamp),
        // otherwise (succeeded) the pending entry is cleared (amount == 0).
        // We encode that: reverted implies (p_asset != asset || p_amount == 0 || p_unlockTime >= block.timestamp),
        // and !reverted implies a_amount == 0.
        assert(
            (reverted && (p_asset != asset || p_amount == 0 || p_unlockTime >= block.timestamp))
            || (!reverted && a_amount == 0)
        );
    }

    receive() external payable {}
}

