    function run(address targetContract, address asset, uint256 preAmount) public payable {
        require(true);

        // Read pending entry for this test contract (msg.sender for c will be this contract)
        // Use the auto-generated getter: pendingFlashDecision(targetContract, address(this)) returns (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable) but in C it's a struct with fields in order: amount, unlockTime, asset, assetBurnable
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Record c balance and this contract balance before the call
        uint256 cBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;

