contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive a scenario to observe withdrawGovernanceAsset behavior.
    // Params:
    // - targetContract: the key used for pendingFlashDecision mapping
    // - asset: the asset address expected by pendingFlashDecision
    // - amount: the amount that was pending (we will not actually ensure ERC20 transfer succeeds, so we only assert on observable contract state when call returns)
    // - unlockTimeOffset: how much in the future unlockTime is set relative to block.timestamp when configured into flashGovernanceConfig
    // The test will try to call withdrawGovernanceAsset from this contract (msg.sender is this test contract).
    function run(address targetContract, address asset, uint256 amount, uint256 unlockTimeOffset) public payable {
        require(targetContract != address(0));
        require(asset != address(0));

        // Configure flashGovernanceConfig via onlySuccessfulProposal function. That modifier requires msg.sender to be a successful proposal
        // which we cannot satisfy here, so we cannot call configureFlashGovernance. Instead we observe withdrawGovernanceAsset behavior strictly via its public surface:
        // We will attempt withdrawGovernanceAsset and capture whether it reverted. Then we assert the general rule:
        // If the call succeeds then (1) the pending entry for (targetContract, msg.sender) had matching asset and unlockTime < block.timestamp and amount>0
        // and after the call the pending entry is cleared (its amount becomes 0). If it reverted, then at least one of those preconditions was false.

        // Read-before state for the pending entry using the auto getter:
        (uint256 pre_amount, uint256 pre_unlockTime, address pre_asset, bool pre_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read-after state
        (uint256 post_amount, uint256 post_unlockTime, address post_asset, bool post_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Construct the assertion expressing the invariant described above.
        // If call succeeded then preconditions must have held and the pending entry must be cleared (post_amount == 0).
        // If call reverted then at least one precondition did not hold.
        // We express: (!reverted) => (pre_asset == asset && pre_amount > 0 && pre_unlockTime < block.timestamp && post_amount == 0)
        // and (reverted) => ( !(pre_asset == asset && pre_amount > 0 && pre_unlockTime < block.timestamp) )
        // Combine into single boolean
        bool ok;
        if (!reverted) {
            ok = (pre_asset == asset) && (pre_amount > 0) && (pre_unlockTime < block.timestamp) && (post_amount == 0);
        } else {
            ok = !( (pre_asset == asset) && (pre_amount > 0) && (pre_unlockTime < block.timestamp) );
        }

        assert(ok);
    }

    receive() external payable {}
 }

