contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to withdraw a pending flash governance deposit for msg.sender = this contract.
    // Parameters:
    // targetContract - the target whose pendingFlashDecision mapping is consulted
    // asset - the asset address to withdraw (must match pending entry)
    // pre_amount - an amount to compare with what withdraw actually transfers (observer only)
    function run(address targetContract, address asset, uint256 pre_amount) public payable {
        require(true);

        // Read visible pending entry fields before: use the public getter for the mapping
        // The mapping is: mapping(address => mapping(address => FlashGovernanceConfig)) public pendingFlashDecision;
        // Its auto-getter has signature: (address,address) -> (uint256,uint256,address,bool) in same order as struct
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Attempt the withdrawal and capture whether it reverted.
        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending entry after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // General rule to assert:
        // If withdrawGovernanceAsset reverted, then the before entry must not have been withdrawable per the require in C.
        // If it did not revert, then the contract must have transferred the exact before_amount and cleared the pending entry (after_amount == 0).
        // We cannot observe token balances here, so instead we assert that a successful call clears the pending entry and that a reverted call implies one of the require conditions failed.

        // Construct conditions that mirror the withdrawGovernanceAsset require predicate:
        bool predicate_ok = (before_asset == asset) && (before_amount > 0) && (before_unlockTime < block.timestamp);

        // Now assert the general rule described above.
        assert(
            // either it reverted and the predicate was false
            (reverted && !predicate_ok)
            // or it succeeded and the pending entry was cleared to zero amount and asset mismatch is impossible after successful withdraw
            || (!reverted && after_amount == 0)
        );
    }

    receive() external payable {}
}
